#!/usr/bin/env python3
"""Write complete clients/tt-ui tree (fixed compile errors). Run from repo root:
   python3 scripts/fix_tt_ui.py
   # or: python3 scripts/fix_tt_ui.py /path/to/tt
"""
from pathlib import Path
import sys

ROOT = Path(sys.argv[1] if len(sys.argv) > 1 else ".")

FILES = {
    'clients/tt-ui/Cargo.toml': '[package]\nname = "tt-ui"\nversion.workspace = true\nedition.workspace = true\nauthors.workspace = true\nlicense.workspace = true\npublish.workspace = true\ndescription = "Turing Tarpit shared Dioxus UI (theme, shell, pages)"\n\n[dependencies]\ndioxus = { version = "0.6", features = ["router"] }\ndioxus-free-icons = { version = "0.9", features = ["bootstrap", "lucide"] }\nserde = { workspace = true }\nserde_json = { workspace = true }\nchrono = { workspace = true }\nuuid = { workspace = true }\nreqwest = { workspace = true }\ntracing = { workspace = true }\n',
    'clients/tt-ui/src/lib.rs': '//! Shared Turing Tarpit Dioxus UI.\n\npub mod api;\npub mod components;\npub mod logo;\npub mod pages;\npub mod theme;\n\nuse dioxus::prelude::*;\n\nuse components::sidebar::Sidebar;\nuse pages::agents::AgentsPage;\nuse pages::inbox::InboxPage;\nuse pages::projects::ProjectsPage;\n\n#[derive(Clone, Routable, Debug, PartialEq)]\n#[rustfmt::skip]\npub enum Route {\n    #[layout(AppShell)]\n        #[route("/")]\n        Projects {},\n        #[route("/inbox")]\n        Inbox {},\n        #[route("/agents")]\n        Agents {},\n}\n\n#[component]\nfn AppShell() -> Element {\n    rsx! {\n        style { { theme::global_css() } }\n        div {\n            style: "display:flex;min-height:100vh;background:var(--tt-surface-muted);",\n            Sidebar {}\n            main {\n                style: "flex:1;min-width:0;background:var(--tt-surface-muted);",\n                Outlet::<Route> {}\n            }\n        }\n    }\n}\n\n#[component]\npub fn Projects() -> Element {\n    rsx! { ProjectsPage {} }\n}\n\n#[component]\npub fn Inbox() -> Element {\n    rsx! { InboxPage {} }\n}\n\n#[component]\npub fn Agents() -> Element {\n    rsx! { AgentsPage {} }\n}\n\n#[component]\npub fn App() -> Element {\n    rsx! {\n        Router::<Route> {}\n    }\n}\n',
    'clients/tt-ui/src/theme.rs': '//! Turing Tarpit design tokens.\n\npub const ORANGE: &str = "#ff3c00";\npub const ORANGE_HOVER: &str = "#e63500";\npub const ORANGE_SOFT: &str = "rgba(255, 60, 0, 0.12)";\npub const BLACK: &str = "#0a0a0a";\npub const BLACK_ELEVATED: &str = "#141414";\npub const GREY: &str = "#6b7280";\npub const GREY_BORDER: &str = "#e5e7eb";\npub const IVORY: &str = "#fafaf7";\npub const MINT: &str = "#c4ebcc";\npub const SURFACE: &str = "#ffffff";\npub const SURFACE_MUTED: &str = "#f4f4f5";\npub const TEXT: &str = "#18181b";\npub const TEXT_MUTED: &str = "#71717a";\npub const SIDEBAR_W: &str = "260px";\n\npub fn global_css() -> String {\n    format!(\n        r#"\n        :root {{\n            --tt-orange: {ORANGE};\n            --tt-orange-hover: {ORANGE_HOVER};\n            --tt-orange-soft: {ORANGE_SOFT};\n            --tt-black: {BLACK};\n            --tt-black-elevated: {BLACK_ELEVATED};\n            --tt-grey: {GREY};\n            --tt-border: {GREY_BORDER};\n            --tt-ivory: {IVORY};\n            --tt-mint: {MINT};\n            --tt-surface: {SURFACE};\n            --tt-surface-muted: {SURFACE_MUTED};\n            --tt-text: {TEXT};\n            --tt-text-muted: {TEXT_MUTED};\n            --tt-sidebar-w: {SIDEBAR_W};\n            --tt-radius: 12px;\n            --tt-radius-sm: 8px;\n            --tt-font: "Inter", system-ui, -apple-system, sans-serif;\n        }}\n        * {{ box-sizing: border-box; }}\n        html, body {{\n            margin: 0; padding: 0; height: 100%;\n            font-family: var(--tt-font);\n            color: var(--tt-text);\n            background: var(--tt-surface-muted);\n            -webkit-font-smoothing: antialiased;\n        }}\n        button {{ font-family: inherit; cursor: pointer; }}\n        a {{ color: inherit; text-decoration: none; }}\n        "#\n    )\n}\n',
    'clients/tt-ui/src/logo.rs': 'use dioxus::prelude::*;\n\n#[component]\npub fn TtMark(#[props(default = 36)] size: u32) -> Element {\n    rsx! {\n        svg {\n            width: "{size}",\n            height: "{size}",\n            view_box: "0 0 64 64",\n            xmlns: "http://www.w3.org/2000/svg",\n            rect { x: "0", y: "0", width: "64", height: "64", rx: "14", fill: "#0a0a0a" }\n            rect { x: "4", y: "4", width: "56", height: "56", rx: "11", fill: "#ff3c00" }\n            path {\n                d: "M13 21.5 C13 21.5 50.5 20.5 51 21.5",\n                stroke: "#fafaf7",\n                stroke_width: "7.2",\n                stroke_linecap: "round",\n                fill: "none",\n            }\n            path {\n                d: "M23.5 21.5 L23.5 47.5",\n                stroke: "#fafaf7",\n                stroke_width: "6.4",\n                stroke_linecap: "round",\n            }\n            path {\n                d: "M40.5 21.5 L40.5 47.5",\n                stroke: "#fafaf7",\n                stroke_width: "6.4",\n                stroke_linecap: "round",\n            }\n        }\n    }\n}\n\n#[component]\npub fn TtWordmark() -> Element {\n    rsx! {\n        div {\n            style: "display:flex;align-items:center;gap:10px;",\n            TtMark { size: 32 }\n            span {\n                style: "font-weight:700;font-size:1.15rem;letter-spacing:-0.02em;color:var(--tt-text);",\n                "Turing Tarpit"\n            }\n        }\n    }\n}\n',
    'clients/tt-ui/src/api/mod.rs': '//! HTTP/RPC client surface for the TT backend.\n\nuse serde::{Deserialize, Serialize};\n\n#[derive(Clone, Debug, Default)]\npub struct TtClient {\n    pub base_url: String,\n    pub token: Option<String>,\n}\n\nimpl TtClient {\n    pub fn new(base_url: impl Into<String>) -> Self {\n        Self {\n            base_url: base_url.into().trim_end_matches(\'/\').to_string(),\n            token: None,\n        }\n    }\n\n    pub fn with_token(mut self, token: impl Into<String>) -> Self {\n        self.token = Some(token.into());\n        self\n    }\n}\n\n#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]\npub struct ActivityItem {\n    pub id: String,\n    pub actor: String,\n    pub action: String,\n    pub target: String,\n    pub detail: Option<String>,\n    pub time_ago: String,\n    pub kind: String,\n}\n\n#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]\npub struct RepoRow {\n    pub name: String,\n    pub full_name: String,\n    pub branch: String,\n    pub commits: u32,\n    pub prs: u32,\n    pub issues: u32,\n    pub updated: String,\n}\n\npub fn mock_activity() -> Vec<ActivityItem> {\n    vec![\n        ActivityItem {\n            id: "1".into(),\n            actor: "Rick".into(),\n            action: "updated a pull request".into(),\n            target: "On-call burden inbound requests".into(),\n            detail: Some("Rick re-score: fix systematic defects".into()),\n            time_ago: "6 hours ago".into(),\n            kind: "pr".into(),\n        },\n        ActivityItem {\n            id: "2".into(),\n            actor: "Morty".into(),\n            action: "opened a pull request".into(),\n            target: "On-call burden inbound requests".into(),\n            detail: Some("Add enriched inbound request dataset".into()),\n            time_ago: "7 hours ago".into(),\n            kind: "pr".into(),\n        },\n        ActivityItem {\n            id: "3".into(),\n            actor: "Morty".into(),\n            action: "created the repository".into(),\n            target: "turing-tarpit".into(),\n            detail: None,\n            time_ago: "7 hours ago".into(),\n            kind: "repo".into(),\n        },\n    ]\n}\n\npub fn mock_repos() -> Vec<RepoRow> {\n    vec![\n        RepoRow {\n            name: "turing-tarpit".into(),\n            full_name: "alice/turing-tarpit".into(),\n            branch: "main".into(),\n            commits: 128,\n            prs: 12,\n            issues: 7,\n            updated: "2 hours ago".into(),\n        },\n        RepoRow {\n            name: "tt-node".into(),\n            full_name: "alice/tt-node".into(),\n            branch: "main".into(),\n            commits: 44,\n            prs: 3,\n            issues: 1,\n            updated: "1 day ago".into(),\n        },\n    ]\n}\n',
    'clients/tt-ui/src/components/mod.rs': 'pub mod activity_feed;\npub mod sidebar;\npub mod stat_card;\npub mod topbar;\n',
    'clients/tt-ui/src/components/topbar.rs': 'use dioxus::prelude::*;\n\n#[component]\npub fn TopBar(title: String, subtitle: Option<String>) -> Element {\n    rsx! {\n        div {\n            h1 {\n                style: "margin:0;font-size:1.6rem;font-weight:700;letter-spacing:-0.03em;color:var(--tt-text);",\n                "{title}"\n            }\n            if let Some(sub) = subtitle {\n                p {\n                    style: "margin:6px 0 0;color:var(--tt-text-muted);font-size:0.95rem;",\n                    "{sub}"\n                }\n            }\n        }\n    }\n}\n',
    'clients/tt-ui/src/components/stat_card.rs': 'use dioxus::prelude::*;\n\n#[component]\npub fn StatCard(label: String, value: String) -> Element {\n    rsx! {\n        div {\n            style: "background:var(--tt-surface);border:1px solid var(--tt-border);border-radius:var(--tt-radius);padding:14px 16px;",\n            div { style: "font-size:0.78rem;color:var(--tt-text-muted);margin-bottom:6px;", "{label}" }\n            div { style: "font-size:1.4rem;font-weight:700;letter-spacing:-0.03em;", "{value}" }\n        }\n    }\n}\n',
    'clients/tt-ui/src/components/activity_feed.rs': 'use dioxus::prelude::*;\n\nuse crate::api::ActivityItem;\n\n#[component]\npub fn ActivityFeed(items: Vec<ActivityItem>) -> Element {\n    rsx! {\n        div {\n            style: "display:flex;flex-direction:column;",\n            for item in items {\n                div {\n                    key: "{item.id}",\n                    style: "display:flex;gap:14px;padding:16px 0;border-bottom:1px solid var(--tt-border);",\n                    div {\n                        style: "width:36px;height:36px;border-radius:999px;background:linear-gradient(135deg,#ff3c00,#f97316);color:#fff;display:flex;align-items:center;justify-content:center;font-size:0.75rem;font-weight:700;flex-shrink:0;",\n                        "{item.actor.chars().next().unwrap_or(\'?\')}"\n                    }\n                    div {\n                        style: "flex:1;min-width:0;",\n                        div {\n                            style: "display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;",\n                            span { style: "font-weight:600;", "{item.actor}" }\n                            span { style: "color:var(--tt-text-muted);", "{item.action}" }\n                            span { style: "font-weight:600;", "{item.target}" }\n                            span {\n                                style: "margin-left:auto;font-size:0.8rem;color:var(--tt-text-muted);",\n                                "{item.time_ago}"\n                            }\n                        }\n                        if let Some(detail) = &item.detail {\n                            div {\n                                style: "margin-top:8px;color:var(--tt-text-muted);font-size:0.9rem;",\n                                "{detail}"\n                            }\n                        }\n                    }\n                }\n            }\n        }\n    }\n}\n',
    'clients/tt-ui/src/components/sidebar.rs': 'use dioxus::prelude::*;\n\nuse crate::logo::TtMark;\nuse crate::Route;\n\n#[component]\npub fn Sidebar() -> Element {\n    rsx! {\n        aside {\n            style: "width:var(--tt-sidebar-w);min-height:100vh;background:var(--tt-black);color:#fafaf7;display:flex;flex-direction:column;padding:16px 12px;position:sticky;top:0;height:100vh;",\n            div {\n                style: "display:flex;align-items:center;gap:10px;padding:8px 10px 20px;",\n                TtMark { size: 34 }\n                span {\n                    style: "font-weight:700;font-size:1rem;letter-spacing:-0.03em;",\n                    "Turing Tarpit"\n                }\n            }\n            nav {\n                style: "display:flex;flex-direction:column;gap:2px;flex:1;",\n                Link {\n                    to: Route::Projects {},\n                    style: "display:block;padding:9px 12px;border-radius:8px;font-weight:500;background:rgba(255,60,0,0.15);color:#ff3c00;",\n                    "Projects"\n                }\n                Link {\n                    to: Route::Inbox {},\n                    style: "display:block;padding:9px 12px;border-radius:8px;font-weight:500;color:#d4d4d8;",\n                    "Inbox"\n                }\n                Link {\n                    to: Route::Agents {},\n                    style: "display:block;padding:9px 12px;border-radius:8px;font-weight:500;color:#d4d4d8;",\n                    "Agents"\n                }\n                div {\n                    style: "margin:16px 10px 8px;font-size:0.7rem;text-transform:uppercase;letter-spacing:0.06em;color:#71717a;",\n                    "Channels"\n                }\n                for name in ["rust", "turing-tarpit", "ship", "design"] {\n                    div {\n                        style: "padding:7px 12px;color:#a1a1aa;font-size:0.85rem;",\n                        "# {name}"\n                    }\n                }\n            }\n            div {\n                style: "padding:12px 8px;border-top:1px solid #222;display:flex;align-items:center;gap:8px;",\n                div {\n                    style: "width:28px;height:28px;border-radius:50%;background:var(--tt-orange);display:flex;align-items:center;justify-content:center;font-size:0.75rem;font-weight:700;color:#fff;",\n                    "A"\n                }\n                span { style: "flex:1;font-size:0.85rem;", "alice" }\n            }\n        }\n    }\n}\n',
    'clients/tt-ui/src/pages/mod.rs': 'pub mod agents;\npub mod inbox;\npub mod projects;\n',
    'clients/tt-ui/src/pages/projects.rs': 'use dioxus::prelude::*;\n\nuse crate::api::mock_activity;\nuse crate::components::activity_feed::ActivityFeed;\nuse crate::components::stat_card::StatCard;\nuse crate::components::topbar::TopBar;\n\n#[component]\npub fn ProjectsPage() -> Element {\n    let activity = mock_activity();\n    rsx! {\n        div {\n            style: "padding:28px 32px 48px;max-width:1200px;",\n            TopBar {\n                title: "Projects".to_string(),\n                subtitle: Some("Set up and manage your projects.".to_string()),\n            }\n            div {\n                style: "display:grid;grid-template-columns:1fr 280px;gap:28px;margin-top:24px;",\n                div {\n                    style: "background:var(--tt-surface);border:1px solid var(--tt-border);border-radius:var(--tt-radius);padding:8px 20px 20px;",\n                    ActivityFeed { items: activity }\n                }\n                aside {\n                    style: "display:flex;flex-direction:column;gap:12px;",\n                    div {\n                        style: "display:grid;grid-template-columns:1fr 1fr;gap:10px;",\n                        StatCard { label: "Projects".to_string(), value: "116".to_string() }\n                        StatCard { label: "Repositories".to_string(), value: "120".to_string() }\n                        StatCard { label: "Pull requests".to_string(), value: "212".to_string() }\n                        StatCard { label: "Issues".to_string(), value: "56".to_string() }\n                    }\n                }\n            }\n        }\n    }\n}\n',
    'clients/tt-ui/src/pages/inbox.rs': 'use dioxus::prelude::*;\n\nuse crate::components::topbar::TopBar;\n\n#[component]\npub fn InboxPage() -> Element {\n    rsx! {\n        div {\n            style: "padding:28px 32px;",\n            TopBar {\n                title: "Inbox".to_string(),\n                subtitle: None,\n            }\n            p {\n                style: "margin-top:16px;color:var(--tt-text-muted);",\n                "Notifications and issue threads will stream over gRPC-Web."\n            }\n        }\n    }\n}\n',
    'clients/tt-ui/src/pages/agents.rs': 'use dioxus::prelude::*;\n\nuse crate::components::topbar::TopBar;\n\n#[component]\npub fn AgentsPage() -> Element {\n    rsx! {\n        div {\n            style: "padding:28px 32px;",\n            TopBar {\n                title: "Agents".to_string(),\n                subtitle: Some("Pearl and workspace agents.".to_string()),\n            }\n            div {\n                style: "margin-top:24px;border:1px solid var(--tt-border);border-radius:var(--tt-radius);padding:20px;background:var(--tt-surface);max-width:360px;",\n                div { style: "font-weight:700;margin-bottom:8px;", "Pearl" }\n                p {\n                    style: "margin:0;color:var(--tt-text-muted);font-size:0.9rem;",\n                    "Workspace co-pilot. Scarlet secrets never enter the model context."\n                }\n            }\n        }\n    }\n}\n',

}

for rel, content in FILES.items():
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content)
    print("write", p)

print("done — run: cargo check -p tt-ui")
